head.b:skin:
body { margin: 0; padding: 0; background-color: #fafaf9; color: #1c1917; }

/* --- STYLING OTOMATIS UNTUK ADMIN AWAM (SMART UI) --- */
.post-body { font-size: 1.1rem; }
.post-body p { margin-bottom: 1.5rem; line-height: 1.8; color: #44403c; }

/* Gambar Otomatis Bagus */
.post-body img { 
    border-radius: 1.5rem; 
    margin: 2rem auto; 
    display: block; 
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.1);
    max-width: 100%;
    height: auto;
}

/* Tombol WA Otomatis */
.post-body a[href*="wa.me"], .post-body a[href*="whatsapp.com"] {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background-color: #25D366;
    color: white !important;
    padding: 12px 24px;
    border-radius: 12px;
    font-weight: 700;
    text-decoration: none;
    margin: 10px 0;
    transition: all 0.3s;
}
.post-body a[href*="wa.me"]:before, .post-body a[href*="whatsapp.com"]:before { content: '\f232'; font-family: 'Font Awesome 6 Brands'; }

/* Tombol Maps Otomatis */
.post-body a[href*="googleusercontent.com/maps"], .post-body a[href*="goo.gl/maps"], .post-body a[href*="maps.app.goo.gl"] {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background-color: #4285F4;
    color: white !important;
    padding: 12px 24px;
    border-radius: 12px;
    font-weight: 700;
    text-decoration: none;
    margin: 10px 0;
    transition: all 0.3s;
}
.post-body a[href*="googleusercontent.com/maps"]:before, .post-body a[href*="goo.gl/maps"]:before, .post-body a[href*="maps.app.goo.gl"]:before { content: '\f3c5'; font-family: 'Font Awesome 6 Free'; font-weight: 900; }

.post-body a:hover { opacity: 0.9; transform: translateY(-2px); }

/* Existing Rules */
.widget-item-control, .post-feader, .post-footer, #navbar-iframe { display: none !important; }
html { scroll-behavior: smooth; }
#hero-slider { transition: background-image 1.5s ease-in-out; }

body.script:
//
    document.addEventListener('DOMContentLoaded', () => {

        // 0. MOBILE MENU TOGGLE
        const mobileBtn = document.getElementById('mobile-menu-btn');
        const mobileMenu = document.getElementById('mobile-menu');

        if (mobileBtn && mobileMenu) {
            mobileBtn.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
                const icon = mobileBtn.querySelector('i');
                if (mobileMenu.classList.contains('hidden')) {
                    icon.classList.remove('fa-times');
                    icon.classList.add('fa-bars');
                } else {
                    icon.classList.remove('fa-bars');
                    icon.classList.add('fa-times');
                }
            });
        }

        // 1. HERO SLIDER
        const heroSlider = document.getElementById('hero-slider');
        if (heroSlider) {
            const heroImages = [
                'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1600&q=80',
                'https://images.unsplash.com/photo-1606760227091-3dd870d97f1d?auto=format&fit=crop&w=1600&q=80'
            ];
            let currentImgIndex = 0;
            setInterval(() => {
                currentImgIndex = (currentImgIndex + 1) % heroImages.length;
                heroSlider.style.backgroundImage = `url('${heroImages[currentImgIndex]}')`;
            }, 4000);
        }

        // --- 2. PERBAIKAN GAMBAR NGEBLUR ---
        function getImageUrl(entry) {
            let img = 'https://placehold.co/800x600/f5f5f4/44403c.png?text=Tanpa+Gambar';
            if (entry.media$thumbnail) {
                let url = entry.media$thumbnail.url;
                // Regex diperbarui untuk menangani format URL Blogger lama (/s...) dan baru (=s...) 
                // dan memaksanya ke resolusi tinggi (w800-h600)
                img = url.replace(/\/s[0-9]+(\-c)?\//, '/w800-h600-c/').replace(/\=s[0-9]+(\-c)?/, '=w800-h600-c');
            } else if (entry.content && entry.content.$t) {
                let match = entry.content.$t.match(/<img[^>]+src="([^">]+)"/);
                if (match) img = match[1];
            }
            return img;
        }

        // --- 3. DESAIN CARD BARU (LEBIH MODERN & CLEAN) ---
        function createCardHTML(title, link, img, snippet, kategoriLabel) {
            return `
            <a href="${link}" class="group flex flex-col bg-white rounded-3xl border border-gray-100 shadow-[0_2px_15px_-3px_rgba(0,0,0,0.04)] hover:shadow-[0_15px_35px_-5px_rgba(13,148,136,0.15)] hover:border-teal-100 transition-all duration-500 overflow-hidden h-full transform hover:-translate-y-1">

                <div class="relative w-full aspect-[4/3] overflow-hidden bg-gray-50">
                    <img src="${img}" class="absolute inset-0 w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700 ease-out" alt="${title}" loading="lazy">
                    <div class="absolute inset-0 bg-gradient-to-t from-gray-900/50 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>

                    <div class="absolute top-4 left-4">
                        <span class="px-3 py-1.5 bg-white/95 backdrop-blur-md text-teal-700 text-xs font-bold rounded-full shadow-sm tracking-wide border border-teal-50">${kategoriLabel}</span>
                    </div>
                </div>

                <div class="p-6 flex flex-col flex-grow relative bg-white">
                    <h3 class="font-extrabold text-xl text-gray-900 group-hover:text-teal-600 transition-colors mb-3 line-clamp-2 leading-tight">${title}</h3>
                    <p class="text-sm text-gray-500 line-clamp-3 leading-relaxed mb-6 flex-grow">${snippet}</p>

                    <div class="mt-auto flex items-center justify-between border-t border-gray-50 pt-5">
                        <span class="text-teal-600 font-bold text-sm tracking-wide group-hover:underline decoration-2 underline-offset-4">Lihat Detail</span>
                        <div class="w-8 h-8 rounded-full bg-teal-50 flex items-center justify-center group-hover:bg-teal-600 group-hover:text-white text-teal-600 transition-all duration-300 transform group-hover:rotate-45">
                            <i class="fas fa-arrow-right text-xs"></i>
                        </div>
                    </div>
                </div>
            </a>`;
        }

        // 4. RENDER KATEGORI HOMEPAGE
        const container = document.getElementById('kategori-container');
        if (container && (window.location.pathname === '/' || window.location.pathname === '/index.html')) {
            const daftarKategori = ['Kuliner', 'Perdagangan', 'Jasa', 'Kerajinan & Produksi', 'Agrobisnis & Peternakan'];
            container.innerHTML = ''; 

            daftarKategori.forEach(kategori => {
                const sectionHtml = `
                    <div class="mb-20">
                        <div class="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
                            <div class="flex items-center gap-3">
                                <div class="w-2 h-8 bg-teal-500 rounded-full"></div>
                                <h3 class="text-3xl font-extrabold text-gray-900 tracking-tight">${kategori}</h3>
                            </div>
                            <a href="/search/label/${encodeURIComponent(kategori)}" class="group text-teal-600 font-bold hover:text-teal-800 flex items-center gap-2 text-sm bg-teal-50 hover:bg-teal-100 px-5 py-2.5 rounded-full transition-colors">
                                Lihat Semua <i class="fas fa-arrow-right transform group-hover:translate-x-1 transition-transform"></i>
                            </a>
                        </div>
                        <div id="grid-${kategori.replace(/\s+/g, '-')}" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8"></div>
                    </div>
                `;
                container.insertAdjacentHTML('beforeend', sectionHtml);

                fetch(`/feeds/posts/default/-/${encodeURIComponent(kategori)}?alt=json&max-results=4`)
                .then(res => res.json())
                .then(data => {
                    const gridEl = document.getElementById(`grid-${kategori.replace(/\s+/g, '-')}`);
                    const entries = data.feed.entry || [];
                    if(entries.length === 0) {
                        gridEl.innerHTML = `<p class="text-gray-400 italic col-span-full bg-gray-50 p-8 rounded-3xl text-center border border-dashed border-gray-200">Belum ada produk untuk kategori ini.</p>`;
                        return;
                    }
                    let cardsHtml = '';
                    entries.forEach(entry => {
                        let title = entry.title.$t;
                        let link = entry.link.find(l => l.rel === 'alternate').href;
                        let img = getImageUrl(entry);
                        let snippet = entry.summary ? entry.summary.$t.substring(0, 85) + '...' : (entry.content ? entry.content.$t.replace(/(<([^>]+)>)/gi, "").substring(0, 85) + '...' : '');

                        // Kirim nama kategori ke dalam fungsi pembuat Card
                        cardsHtml += createCardHTML(title, link, img, snippet, kategori);
                    });
                    gridEl.innerHTML = cardsHtml;
                }).catch(() => {});
            });
        }

        // 5. REKOMENDASI SINGLE PAGE
        const rekomendasiGrid = document.getElementById('rekomendasi-grid');
        if (rekomendasiGrid && window.location.href.indexOf('.html') > -1) {
            fetch('/feeds/posts/default?alt=json&max-results=5')
            .then(res => res.json())
            .then(data => {
                const entries = data.feed.entry || [];
                let html = '';
                let count = 0;
                let currentTitle = document.title;

                entries.forEach(entry => {
                    if(count >= 4) return; 
                    let title = entry.title.$t;
                    if(currentTitle.indexOf(title) > -1) return;

                    let link = entry.link.find(l => l.rel === 'alternate').href;
                    let img = getImageUrl(entry);
                    let snippet = entry.summary ? entry.summary.$t.substring(0, 85) + '...' : '';

                    // Di halaman single post, labelnya diset "Rekomendasi"
                    html += createCardHTML(title, link, img, snippet, "Rekomendasi");
                    count++;
                });
                rekomendasiGrid.innerHTML = html !== '' ? html : '<p class="text-gray-400 italic">Belum ada rekomendasi.</p>';
            }).catch(() => {});
        }
    });
//
